import { useState } from "react";

export default function Counter() {
  const [count, setCount] = useState(0);
  return <button onClick={() => setCount(c => c + 1)}>Count: {count}</button>;
}

import { useState } from "react";

export default function Checklist() {
  const [done, setDone] = useState(false);
  return <button onClick={() => setDone(value => !value)}>{done ? "Completed" : "Mark complete"}</button>;
}

import { useState } from "react";

export default function XP() {
  const [xp, setXp] = useState(0);
  return <button onClick={() => setXp(value => value + 5)}>XP: {xp}</button>;
}

import { useState } from "react";

export default function NameForm() {
  const [name, setName] = useState("");
  return <label>Name <input value={name} onChange={e => setName(e.target.value)} /></label>;
}
